"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../components/ui/Button";
import { Card } from "../../components/ui/Card";

interface Appointment {
    id: number;
    time: string;
    client: string;
    service: string;
    price: string;
    status: 'CONFIRMADO' | 'PENDENTE' | 'CANCELADO' | 'INDISPONÍVEL';
}

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function BarberDashboard() {
    const [appointments, setAppointments] = useState<Appointment[]>([
        { id: 1, time: "09:00", client: "João Santos", service: "Corte + Barba", price: "R$ 65", status: "CONFIRMADO" },
        { id: 2, time: "10:00", client: "Pedro Lima", service: "Corte Degradê", price: "R$ 45", status: "CONFIRMADO" },
        { id: 3, time: "10:30", client: "Lucas Oliveira", service: "Barba", price: "R$ 30", status: "PENDENTE" },
        { id: 4, time: "11:00", client: "Marcos Costa", service: "Corte Social", price: "R$ 40", status: "CONFIRMADO" },
        { id: 5, time: "14:00", client: "Vago", service: "Horário Disponível", price: "-", status: "CONFIRMADO" },
    ]);

    const handleStatusChange = (id: number, newStatus: Appointment['status']) => {
        setAppointments(prev => prev.map(apt =>
            apt.id === id ? { ...apt, status: newStatus } : apt
        ));
    };

    const handleCancel = (id: number) => {
        if (typeof window !== "undefined" && window.confirm("Deseja realmente cancelar este agendamento?")) {
            handleStatusChange(id, 'CANCELADO');
        }
    };

    const toggleAvailability = (id: number) => {
        setAppointments(prev => prev.map(apt => {
            if (apt.id === id) {
                const isIndisponivel = apt.status === 'INDISPONÍVEL';
                return {
                    ...apt,
                    status: isIndisponivel ? 'CONFIRMADO' : 'INDISPONÍVEL',
                    client: isIndisponivel ? 'Vago' : 'HORÁRIO BLOQUEADO',
                    service: isIndisponivel ? 'Horário Disponível' : 'INDISPONÍVEL'
                };
            }
            return apt;
        }));
    };

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black">

            <header className="mb-10 lg:mb-16 animate-fade-in-up">
                <h1 className="text-4xl font-semibold mb-2">
                    Olá, <span className="text-[#D4AF37] italic uppercase tracking-tighter">Carlos</span>
                </h1>
                <p className="text-gray-400 text-sm tracking-wide">Sua agenda de hoje</p>
            </header>

            {/* Stats Cards Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-14">
                {[
                    { icon: "CheckCircle", label: "Atendimentos Hoje", value: "5" },
                    { icon: "DollarSign", label: "Comissão do Mês", value: "R$ 2.340" },
                    { icon: "Star", label: "Avaliação", value: "4.9 ★" },
                    { icon: "Clock", label: "Próximo Cliente", value: "09:00" },
                ].map((stat, i) => (
                    <div key={i} className="bg-[#111111] border border-[#1f1f1f] p-6 rounded-xl hover:border-[#D4AF37]/20 transition-all group">
                        <div className="text-[#D4AF37] mb-4 bg-[#D4AF37]/5 w-10 h-10 rounded-lg flex items-center justify-center group-hover:bg-[#D4AF37]/10 transition-colors">
                            <Icon name={stat.icon} className="w-5 h-5" />
                        </div>
                        <h3 className="text-2xl font-bold mb-1">{stat.value}</h3>
                        <p className="text-gray-500 text-[11px] uppercase tracking-widest font-medium">{stat.label}</p>
                    </div>
                ))}
            </div>

            {/* Agenda Section */}
            <section className="animate-fade-in-up" style={{ animationDelay: '0.1s' }}>
                <div className="flex items-center gap-3 mb-8">
                    <Icon name="Calendar" className="w-5 h-5 text-[#D4AF37]" />
                    <h2 className="text-2xl font-semibold tracking-tight">Agenda — Hoje</h2>
                </div>

                <div className="space-y-4">
                    {appointments.map((apt) => (
                        <div
                            key={apt.id}
                            className={`group flex items-center justify-between p-6 rounded-xl border border-[#1a1a1a] bg-[#111111] hover:border-[#2a2a2a] transition-all ${apt.status === 'CANCELADO' ? 'opacity-30 grayscale' : ''} ${apt.status === 'INDISPONÍVEL' ? 'border-red-500/10 bg-red-500/[0.01]' : ''}`}
                        >
                            <div className="flex items-center gap-10 flex-1">
                                <span className="text-[#D4AF37] font-bold text-base w-14 tracking-wider">
                                    {apt.time}
                                </span>

                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-full bg-[#0a0a0a] border border-[#1f1f1f] flex items-center justify-center text-gray-600">
                                        <Icon name="User" className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <h4 className={`font-semibold text-base ${apt.status === 'INDISPONÍVEL' ? 'text-red-400' : 'text-white'}`}>
                                            {apt.client}
                                        </h4>
                                        <p className="text-gray-500 text-xs mt-0.5 font-medium">{apt.service}</p>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-8">
                                <span className="text-[#D4AF37] font-bold text-lg">
                                    {apt.price}
                                </span>

                                <div className="flex items-center gap-6">
                                    <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-tighter ${apt.status === 'CONFIRMADO' ? 'bg-[#0f2419] text-[#4ade80]' :
                                        apt.status === 'PENDENTE' ? 'bg-[#24210f] text-[#dbac2c]' :
                                            apt.status === 'CANCELADO' ? 'bg-red-900/10 text-red-500' :
                                                'bg-red-900/30 text-red-400'
                                        }`}>
                                        {apt.status}
                                    </span>

                                    <div className="flex items-center gap-2">
                                        {apt.status !== 'CANCELADO' && apt.status !== 'INDISPONÍVEL' && apt.client !== 'Vago' && (
                                            <button
                                                onClick={() => handleCancel(apt.id)}
                                                className="p-2 hover:bg-red-500/10 rounded-lg text-gray-600 hover:text-red-500 transition-all sm:opacity-0 group-hover:opacity-100"
                                                title="Cancelar Agendamento"
                                            >
                                                <Icon name="Ban" className="w-4 h-4" />
                                            </button>
                                        )}

                                        {(apt.client === 'Vago' || apt.status === 'INDISPONÍVEL') && (
                                            <button
                                                onClick={() => toggleAvailability(apt.id)}
                                                className={`p-2 rounded-lg transition-all sm:opacity-0 group-hover:opacity-100 ${apt.status === 'INDISPONÍVEL' ? 'text-emerald-500 hover:bg-emerald-500/10' : 'text-gray-600 hover:text-red-500 hover:bg-red-500/10'}`}
                                                title={apt.status === 'INDISPONÍVEL' ? "Liberar Horário" : "Bloquear Horário"}
                                            >
                                                {apt.status === 'INDISPONÍVEL' ? <Icon name="CircleCheck" className="w-4 h-4" /> : <Icon name="Ban" className="w-4 h-4" />}
                                            </button>
                                        )}

                                        <div className="text-gray-700 group-hover:text-[#D4AF37] transition-colors cursor-pointer pl-2">
                                            <Icon name="ChevronRight" className="w-5 h-5" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </section>

            <footer className="mt-20 border-t border-[#1a1a1a] pt-8 flex justify-between items-center opacity-40">
                <p className="text-[10px] uppercase tracking-[0.5em] text-gray-500">Expert Barber Dashboard v2.0</p>
                <div className="flex gap-4">
                    <div className="w-2 h-2 rounded-full bg-emerald-500" />
                    <span className="text-[9px] uppercase tracking-widest">Sistema Ativo</span>
                </div>
            </footer>
        </div>
    );
}
